@Test
public void testSetPropertyTypeFromEntityIdValue() {
    // A valid item ID is recognized and maps to the item datatype.
    assertEquals(
            DatatypeIdValue.DT_ITEM,
            this.propertyRegister.setPropertyTypeFromEntityIdValue(
                    this.dataObjectFactory.getPropertyIdValue("P1001", this.siteIri),
                    this.dataObjectFactory.getItemIdValue("Q20", this.siteIri)));

    assertEquals(
            DatatypeIdValue.DT_PROPERTY,
            this.propertyRegister.setPropertyTypeFromEntityIdValue(
                    this.dataObjectFactory.getPropertyIdValue("P1001", this.siteIri),
                    this.dataObjectFactory.getPropertyIdValue("P20", this.siteIri)));

    assertEquals(
            DatatypeIdValue.DT_FORM,
            this.propertyRegister.setPropertyTypeFromEntityIdValue(
                    this.dataObjectFactory.getPropertyIdValue("P1001", this.siteIri),
                    this.dataObjectFactory.getFormIdValue("L1-F1", this.siteIri)));

    assertEquals(
            DatatypeIdValue.DT_SENSE,
            this.propertyRegister.setPropertyTypeFromEntityIdValue(
                    this.dataObjectFactory.getPropertyIdValue("P1001", this.siteIri),
                    this.dataObjectFactory.getSenseIdValue("L1-S1", this.siteIri)));

    assertEquals(
            DatatypeIdValue.DT_LEXEME,
            this.propertyRegister.setPropertyTypeFromEntityIdValue(
                    this.dataObjectFactory.getPropertyIdValue("P1001", this.siteIri),
                    this.dataObjectFactory.getLexemeIdValue("L1", this.siteIri)));
}

