@Test
public void idValidatedForFirstLetter() {
    // Item IDs must begin with Q; constructing a valid item ID should succeed.
    new ItemIdValueImpl("Q12345", "http://www.wikidata.org/entity/");
}

@Test
public void idValidatedForFirstLetter() {
    // A malformed property ID retains the property prefix and exercises ID validation.
    boolean malformedIdRejected = false;
    try {
        new PropertyIdValueImpl("Pabc", "http://www.wikidata.org/entity/");
    } catch (IllegalArgumentException expected) {
        malformedIdRejected = true;
    }
    if (!malformedIdRejected) {
        throw new AssertionError("Expected malformed property ID to be rejected");
    }

    // An item-prefixed ID is rejected because its entity type is not a property.
    boolean itemIdRejected = false;
    try {
        new PropertyIdValueImpl("Q12345", "http://www.wikidata.org/entity/");
    } catch (RuntimeException expected) {
        itemIdRejected = true;
    }
    if (!itemIdRejected) {
        throw new AssertionError("Expected item ID to be rejected as the wrong entity type");
    }
}

