    List<? extends MwDumpFile> offlineResults = offlineManager.findAllDumps(DumpContentType.FULL);
    assertEquals(2, offlineResults.size());
    assertEquals("20140220", offlineResults.get(0).getDateStamp());
    assertEquals("20140205", offlineResults.get(1).getDateStamp());
    for (MwDumpFile dumpFile : offlineResults) {
