    setLocalDump("20140220", DumpContentType.DAILY, true);
    WmfDumpFileManager dumpFileManager = new WmfDumpFileManager("wikidatawiki", dm, wrf);
    List<? extends MwDumpFile> missingCurrent =
            dumpFileManager.findAllRelevantRevisionDumps(true);

    assertEquals(1, missingCurrent.size());
    assertEquals(DumpContentType.DAILY, missingCurrent.get(0).getDumpContentType());

    // A FULL main dump and daily dumps on either side exercise the strict date comparison.
    setLocalDump("20140210", DumpContentType.FULL, true);
    setLocalDump("20140209", DumpContentType.DAILY, true);
    setLocalDump("20140210", DumpContentType.DAILY, true);

