    assertEquals("20140210", withFullMain.get(1).getDateStamp());
    assertTrue(withFullMain.get(0) instanceof WmfLocalDumpFile);

    // Equal-date and older daily dumps are excluded; a newer one precedes the main dump.
    setLocalDump("20140220", DumpContentType.CURRENT, true);
    List<? extends MwDumpFile> withCurrentMain =
            dumpFileManager.findAllRelevantRevisionDumps(true);

    // The returned relevant dump is the CURRENT main dump.
