@Test
public void versionComparatorTest2() {
    Assert.assertEquals(0, VersionComparator.INSTANCE.compare("1.12.1", "1.12.1"));
    Assert.assertEquals(0, VersionComparator.INSTANCE.compare(null, null));
    Assert.assertTrue(VersionComparator.INSTANCE.compare(null, "1.12.1") < 0);
    Assert.assertTrue(VersionComparator.INSTANCE.compare("1.12.1", null) > 0);

    Assert.assertTrue(VersionComparator.INSTANCE.compare("", "1") < 0);
    Assert.assertTrue(VersionComparator.INSTANCE.compare("1.2", "1.2.0") < 0);
    Assert.assertTrue(VersionComparator.INSTANCE.compare("1.2.0", "1.2") > 0);

    Assert.assertTrue(VersionComparator.INSTANCE.compare("1.12.1", "1.12.1c") < 0);
    Assert.assertTrue(VersionComparator.INSTANCE.compare("1.12.1c", "1.12.1") > 0);
}

@Test
public void versionComparatorTes6() {
    // Verify equality and null ordering.
    Assert.assertEquals(0, VersionComparator.INSTANCE.compare(null, null));
    Assert.assertEquals(0, VersionComparator.INSTANCE.compare("1.2", "1.2"));
    Assert.assertTrue(VersionComparator.INSTANCE.compare(null, "1.0") < 0);
    Assert.assertTrue(VersionComparator.INSTANCE.compare("1.0", null) > 0);

    // Verify equal-length component comparison and differing component counts.
    Assert.assertTrue(VersionComparator.INSTANCE.compare("1.2", "1.3") < 0);
    Assert.assertTrue(VersionComparator.INSTANCE.compare("1.0", "1.0.1") < 0);

    // Verify numeric ordering when component lengths differ.
    Assert.assertTrue(VersionComparator.INSTANCE.compare("1.0.2", "1.0.10") < 0);
    Assert.assertTrue(VersionComparator.INSTANCE.compare("V0.0.20170102", "V0.0.20170101") > 0);
    Assert.assertTrue(VersionComparator.INSTANCE.compare("V0.0.20170101", "V0.0.20170102") < 0);
}

@Test
public void versionComparatorTest4() {
    // Equal inputs, including nulls, should compare as equal.
    Assert.assertEquals(0, VersionComparator.INSTANCE.compare("1.2", "1.2"));
    Assert.assertEquals(0, VersionComparator.INSTANCE.compare(null, null));

    // Null arguments sort before non-null versions.
    Assert.assertTrue(VersionComparator.INSTANCE.compare(null, "1.0") < 0);
    Assert.assertTrue(VersionComparator.INSTANCE.compare("1.0", null) > 0);

    // Empty input exercises the zero-iteration component loop.
    Assert.assertTrue(VersionComparator.INSTANCE.compare("", "1") < 0);

    // Equal shared components sort by version length.
    Assert.assertTrue(VersionComparator.INSTANCE.compare("1.2", "1.2.0") < 0);
    Assert.assertTrue(VersionComparator.INSTANCE.compare("1.2", "1.2.1") < 0);

    // Equal numeric values in differently sized components leave diff at zero.
    Assert.assertTrue(VersionComparator.INSTANCE.compare("1.2a", "1.2") > 0);

    // Unequal components verify lexical and numeric ordering.
    Assert.assertTrue(VersionComparator.INSTANCE.compare("1.2", "1.3") < 0);
    Assert.assertTrue(VersionComparator.INSTANCE.compare("1.9", "1.10") < 0);
    Assert.assertTrue(VersionComparator.INSTANCE.compare("1.13.0", "1.12.1c") > 0);
    Assert.assertTrue(VersionComparator.INSTANCE.compare("1.12.1c", "1.13.0") < 0);
}

@Test
public void versionComparatorTest5() {
    int compare = VersionComparator.INSTANCE.compare("V1.2", "V1.1");
    Assert.assertTrue(compare > 0);

    compare = VersionComparator.INSTANCE.compare("V1.1", "V1.2");
    Assert.assertTrue(compare < 0);

    // Cover equality, including null equality, and both null argument orders.
    Assert.assertEquals(0, VersionComparator.INSTANCE.compare(null, null));
    Assert.assertEquals(0, VersionComparator.INSTANCE.compare("V1.2", "V1.2"));
    Assert.assertTrue(VersionComparator.INSTANCE.compare(null, "V1.2") < 0);
    Assert.assertTrue(VersionComparator.INSTANCE.compare("V1.2", null) > 0);

    // Cover zero shared segments, unequal numeric segment lengths, and component counts.
    Assert.assertTrue(VersionComparator.INSTANCE.compare("", "1") < 0);
    Assert.assertTrue(VersionComparator.INSTANCE.compare("V1.10", "V1.2") > 0);
    Assert.assertTrue(VersionComparator.INSTANCE.compare("V1.2", "V1.10") < 0);
    Assert.assertTrue(VersionComparator.INSTANCE.compare("1.2", "01.2") < 0);
    Assert.assertTrue(VersionComparator.INSTANCE.compare("V1.2", "V1.2.0") < 0);
}

@Test
public void versionComparatorTest7() {
    int compare = VersionComparator.INSTANCE.compare("1.12.2", "1.12.1c");
    Assert.assertTrue(compare > 0);

    compare = VersionComparator.INSTANCE.compare("1.12.1c", "1.12.2");
    Assert.assertTrue(compare < 0);

    // Equal versions and equal null values compare as zero.
    Assert.assertEquals(0, VersionComparator.INSTANCE.compare("1.12.2", "1.12.2"));
    Assert.assertEquals(0, VersionComparator.INSTANCE.compare(null, null));

    // Cover null ordering in both directions.
    Assert.assertEquals(-1, VersionComparator.INSTANCE.compare(null, "1.0"));
    Assert.assertEquals(1, VersionComparator.INSTANCE.compare("1.0", null));

    // Empty and differing component counts exercise loop boundaries.
    Assert.assertTrue(VersionComparator.INSTANCE.compare("", "1") < 0);
    Assert.assertTrue(VersionComparator.INSTANCE.compare("1.12.2", "1.12.2.1") < 0);

    // Equal-length components require comparison of their values.
    Assert.assertTrue(VersionComparator.INSTANCE.compare("1.12.2", "1.12.3") < 0);

    // Matching numeric prefixes with unequal component lengths keep the diff zero.
    Assert.assertTrue(VersionComparator.INSTANCE.compare("1.2a", "1.2b") < 0);

    // Different-length numeric components are ordered by numeric value, not lexicographically.
    Assert.assertTrue(VersionComparator.INSTANCE.compare("1.2", "1.10") < 0);

    // Equal numeric prefixes with different component lengths retain the length ordering.
    Assert.assertTrue(VersionComparator.INSTANCE.compare("1.2", "1.02") < 0);
}

@Test
public void testFindCNCharNotDensity() {
    final StopWatch stopWatch = new StopWatch();
    final String input = "赵啊三在做什么";
    final NFA NFALocal = new NFA();
    NFALocal.insert("赵", "赵啊", "赵啊三");

    stopWatch.start("automaton_cn_find_not_density");
    final List<FoundWord> result = NFALocal.find(input, false);
    stopWatch.stop();

    // Assert the complete match, including its exact position, on the first search.
    Assert.assertEquals(1, result.size());
    Assert.assertEquals("赵", result.get(0).getWord());
    Assert.assertEquals(Integer.valueOf(0), result.get(0).getBeginIndex());
    Assert.assertEquals(Integer.valueOf(0), result.get(0).getEndIndex());

    // A second call exercises the already-built automaton path.
    final List<FoundWord> secondResult = NFALocal.find(input, false);
    Assert.assertEquals(1, secondResult.size());
    Assert.assertEquals("赵", secondResult.get(0).getWord());
    Assert.assertEquals(Integer.valueOf(0), secondResult.get(0).getBeginIndex());
    Assert.assertEquals(Integer.valueOf(0), secondResult.get(0).getEndIndex());

    // Density matching continues after a match and returns the overlapping word.
    final NFA densityNFA = new NFA();
    densityNFA.insert("赵", "赵啊");
    final List<FoundWord> densityResult = densityNFA.find("赵啊", true);
    Assert.assertEquals(2, densityResult.size());
    Assert.assertEquals("赵", densityResult.get(0).getWord());
    Assert.assertEquals(Integer.valueOf(0), densityResult.get(0).getBeginIndex());
    Assert.assertEquals(Integer.valueOf(0), densityResult.get(0).getEndIndex());
    Assert.assertEquals("赵啊", densityResult.get(1).getWord());
    Assert.assertEquals(Integer.valueOf(0), densityResult.get(1).getBeginIndex());
    Assert.assertEquals(Integer.valueOf(1), densityResult.get(1).getEndIndex());

    final WordTree wordTreeLocal = new WordTree();
    wordTreeLocal.addWords("赵", "赵啊", "赵啊三");
    stopWatch.start("wordtree_cn_find_not_density");
    final List<String> result1 = wordTreeLocal.matchAllWords(input, -1, false, true)
            .stream()
            .map(FoundWord::getWord)
            .collect(Collectors.toList());
    stopWatch.stop();

    Assert.assertEquals(1, result1.size());
    Assert.assertEquals("赵", String.join(",", result1));
}

@Test
public void testFind() {
    final NFA NFA = new NFA();
    NFA.insert("say", "her", "he", "she", "shr");

    final WordTree wordTree = new WordTree();
    wordTree.addWords("say", "her", "he", "she", "shr");

    final StopWatch stopWatch = new StopWatch();
    final String input = "sasherhsay";

    stopWatch.start("automaton_char_find");
    final List<FoundWord> ans1 = NFA.find(input);
    stopWatch.stop();

    Assert.assertEquals("she,he,her,say",
            ans1.stream().map(FoundWord::getWord).collect(Collectors.joining(",")));
    Assert.assertEquals(2, ans1.get(0).getBeginIndex().intValue());
    Assert.assertEquals(4, ans1.get(0).getEndIndex().intValue());
    Assert.assertEquals(3, ans1.get(1).getBeginIndex().intValue());
    Assert.assertEquals(4, ans1.get(1).getEndIndex().intValue());
    Assert.assertEquals(3, ans1.get(2).getBeginIndex().intValue());
    Assert.assertEquals(5, ans1.get(2).getEndIndex().intValue());
    Assert.assertEquals(7, ans1.get(3).getBeginIndex().intValue());
    Assert.assertEquals(9, ans1.get(3).getEndIndex().intValue());

    stopWatch.start("wordtree_char_find");
    final List<String> ans2 = wordTree.matchAll(input, -1, true, true);
    stopWatch.stop();
    Assert.assertEquals("she,he,her,say", String.join(",", ans2));
}

