@Test
public void shouldRollbackOnExplicitFailure() {
    // Failure while ACTIVE must roll back, even if success is called afterward.
    Connection activeConnection = connectionMock();
    ExplicitTransaction activeTx = beginTx(activeConnection);
    activeTx.failure();
    activeTx.success();
    activeTx.close();

    InOrder activeOrder = inOrder(activeConnection);
    activeOrder.verify(activeConnection).run(eq("BEGIN"), any(), any(), any());
    activeOrder.verify(activeConnection).runAndFlush(eq("ROLLBACK"), any(), any(), any());
    activeOrder.verify(activeConnection).release();

    // Failure after success must also mark the transaction failed.
    Connection successfulConnection = connectionMock();
    ExplicitTransaction successfulTx = beginTx(successfulConnection);
    successfulTx.success();
    successfulTx.failure();
    successfulTx.close();

    InOrder successfulOrder = inOrder(successfulConnection);
    successfulOrder.verify(successfulConnection).run(eq("BEGIN"), any(), any(), any());
    successfulOrder.verify(successfulConnection).runAndFlush(eq("ROLLBACK"), any(), any(), any());
    successfulOrder.verify(successfulConnection).release();

    // A repeated failure exercises the condition's false outcome once already failed.
    Connection failedConnection = connectionMock();
    ExplicitTransaction failedTx = beginTx(failedConnection);
    failedTx.failure();
    failedTx.failure();
    failedTx.close();

    InOrder failedOrder = inOrder(failedConnection);
    failedOrder.verify(failedConnection).run(eq("BEGIN"), any(), any(), any());
    failedOrder.verify(failedConnection).runAndFlush(eq("ROLLBACK"), any(), any(), any());
    failedOrder.verify(failedConnection).release();
}

