@Test
public void testFields() throws Exception {
    // Exercise the empty-input branch with an explicitly typed empty list.
    ResultBuilder emptyBuilder = new ResultBuilder("<unknown>", ParameterSupport.NO_PARAMETERS);
    emptyBuilder.keys(new String[0]);
    ResultCursor emptyResult = emptyBuilder.build();
    emptyResult.first();

    List<Pair<String, Integer>> emptyFields = Extract.fields(emptyResult, integerExtractor());
    assertThat(emptyFields, equalTo(Collections.<Pair<String, Integer>>emptyList()));

    // Exercise the multi-key loop and verify both mappings and their order.
    ResultBuilder builder = new ResultBuilder("<unknown>", ParameterSupport.NO_PARAMETERS);
    builder.keys(new String[] { "k1", "k2" });
    builder.record(new Value[] { value(42), value(7) });

    ResultCursor result = builder.build();
    result.first();

    List<Pair<String, Integer>> fields = Extract.fields(result, integerExtractor());
    assertThat(fields, equalTo(Arrays.asList(
            InternalPair.of("k1", 42),
            InternalPair.of("k2", 7))));
}

@Test
public void testProperties() throws Exception {
    Map<String, Value> emptyProps = new HashMap<>();
    InternalNode emptyNode = new InternalNode(42L, Collections.singletonList("L"), emptyProps);
    Iterable<Pair<String, Integer>> emptyProperties = Extract.properties(emptyNode, integerExtractor());
    assertFalse(emptyProperties.iterator().hasNext());

    Map<String, Value> singleProp = new HashMap<>();
    singleProp.put("only", value(43));
    InternalNode singleNode = new InternalNode(42L, Collections.singletonList("L"), singleProp);
    Iterator<Pair<String, Integer>> singleIterator =
            Extract.properties(singleNode, integerExtractor()).iterator();
    assertThat(singleIterator.next(), equalTo(InternalPair.of("only", 43)));
    assertFalse(singleIterator.hasNext());

    Map<String, Value> props = new HashMap<>();
    props.put("k1", value(43));
    props.put("k2", value(42));

    InternalNode node = new InternalNode(42L, Collections.singletonList("L"), props);
    Iterable<Pair<String, Integer>> properties = Extract.properties(node, integerExtractor());
    Iterator<Pair<String, Integer>> iterator = properties.iterator();

    assertThat(iterator.next(), equalTo(InternalPair.of("k1", 43)));
    assertThat(iterator.next(), equalTo(InternalPair.of("k2", 42)));
    assertFalse(iterator.hasNext());
}

