@Test
public void testValidateAndCache() {
    final LocalCachingAuthenticator authenticator =
            new LocalCachingAuthenticator(this.delegate, 10, 2, TimeUnit.SECONDS);

    // A cache miss should initialize the authenticator and populate the cache.
    authenticator.validate(this.credentials, null);
    assertTrue(authenticator.isCached(this.credentials));

    // A second validation with the same cache key should restore the cached profile.
    final CommonProfile cachedProfile = this.credentials.getUserProfile();
    final UsernamePasswordCredentials sameCredentials =
            new UsernamePasswordCredentials("a", "a", this.getClass().getName());
    final CommonProfile differentProfile = new CommonProfile();
    differentProfile.setId("different");
    sameCredentials.setUserProfile(differentProfile);

    authenticator.validate(sameCredentials, null);
    assertSame(cachedProfile, sameCredentials.getUserProfile());
}

