@Test
public void testValidateAndExpire() {
    final LocalCachingAuthenticator authenticator =
            new LocalCachingAuthenticator(this.delegate, 10, 500, TimeUnit.MILLISECONDS);

    // validate() initializes the authenticator and populates the cache.
    authenticator.validate(this.credentials, null);
    assertTrue(authenticator.isCached(this.credentials));

    final CommonProfile cachedProfile = this.credentials.getUserProfile();
    assertNotNull(cachedProfile);

    // Clear the profile so the cache-hit path must restore it.
    this.credentials.setUserProfile(null);
    authenticator.validate(this.credentials, null);
    assertSame(cachedProfile, this.credentials.getUserProfile());

    try {
        Thread.sleep(600);
    } catch (final InterruptedException e) {
        throw new RuntimeException(e);
    }

    assertFalse(authenticator.isCached(this.credentials));
}

@Test
public void testValidateAndCacheAndRemove() {
    final LocalCachingAuthenticator authenticator =
            new LocalCachingAuthenticator(this.delegate, 10, 2, TimeUnit.SECONDS);

