@Test
public void testHeaderOk() throws HttpAction {
    // Preserve the header-match case.
    WebContext headerMatch = MockWebContext.create()
            .addRequestHeader(Pac4jConstants.CSRF_TOKEN, VALUE)
            .addSessionAttribute(Pac4jConstants.CSRF_TOKEN, VALUE);
    Assert.assertTrue(authorizer.isAuthorized(headerMatch, null));

    // A matching request parameter also authorizes the request.
    WebContext parameterMatch = MockWebContext.create()
            .addRequestParameter(Pac4jConstants.CSRF_TOKEN, VALUE)
            .addSessionAttribute(Pac4jConstants.CSRF_TOKEN, VALUE);
    Assert.assertTrue(authorizer.isAuthorized(parameterMatch, null));

    // Checked requests with neither token matching the session token are rejected.
    WebContext tokenMismatch = MockWebContext.create()
            .addRequestParameter(Pac4jConstants.CSRF_TOKEN, "different-parameter")
            .addRequestHeader(Pac4jConstants.CSRF_TOKEN, "different-header")
            .addSessionAttribute(Pac4jConstants.CSRF_TOKEN, VALUE);
    Assert.assertFalse(authorizer.isAuthorized(tokenMismatch, null));

    // With POST-only checking enabled, a GET request skips token checks—even without a session token.
    authorizer.setOnlyCheckPostRequest(true);
    WebContext uncheckedGet = MockWebContext.create();
    Assert.assertTrue(authorizer.isAuthorized(uncheckedGet, null));
}

