@Test
public void testValidateAndCache() throws HttpAction {
    final LocalCachingAuthenticator authenticator =
            new LocalCachingAuthenticator(this.delegate, 10, 2, TimeUnit.SECONDS);
    authenticator.init(null);
    authenticator.validate(this.credentials);

    assertTrue(authenticator.isCached(this.credentials));
    assertNotNull(this.credentials.getUserProfile());
    // Compare with the username used to construct the credentials.
    assertEquals("a", this.credentials.getUserProfile().getId());

    // A failing hashCode triggers the cache lookup exception-handling path.
    final UsernamePasswordCredentials failingCredentials =
            new UsernamePasswordCredentials("broken", "a", this.getClass().getName()) {
                @Override
                public int hashCode() {
                    throw new IllegalStateException("cache lookup failed");
                }
            };

    try {
        authenticator.validate(failingCredentials);
        fail("Expected a CredentialsException");
    } catch (final CredentialsException e) {
        assertTrue(e.getCause() instanceof IllegalStateException);
        assertEquals("cache lookup failed", e.getCause().getMessage());
    }
}

