@Test
public void testHeaderOk() throws RequiresHttpAction {
    // A non-POST request bypasses token validation when POST-only checking is enabled.
    authorizer.setOnlyCheckPostRequest(true);
    WebContext nonPostContext = MockWebContext.create()
            .addRequestHeader(Pac4jConstants.CSRF_TOKEN, "wrong")
            .addSessionAttribute(Pac4jConstants.CSRF_TOKEN, VALUE);
    Assert.assertTrue(authorizer.isAuthorized(nonPostContext, null));

    // A POST request checks tokens and rejects mismatches.
    WebContext postContext = MockWebContext.create()
            .setRequestMethod("POST")
            .addRequestHeader(Pac4jConstants.CSRF_TOKEN, "wrong")
            .addSessionAttribute(Pac4jConstants.CSRF_TOKEN, VALUE);
    Assert.assertFalse(authorizer.isAuthorized(postContext, null));

    WebContext matchingHeaderContext = MockWebContext.create()
            .addRequestHeader(Pac4jConstants.CSRF_TOKEN, VALUE)
            .addSessionAttribute(Pac4jConstants.CSRF_TOKEN, VALUE);
    authorizer.setOnlyCheckPostRequest(false);
    Assert.assertTrue(authorizer.isAuthorized(matchingHeaderContext, null));

    // A matching request parameter independently satisfies the token check.
    WebContext matchingParameterContext = MockWebContext.create()
            .addRequestParameter(Pac4jConstants.CSRF_TOKEN, VALUE)
            .addSessionAttribute(Pac4jConstants.CSRF_TOKEN, VALUE);
    Assert.assertTrue(authorizer.isAuthorized(matchingParameterContext, null));

    WebContext mismatchedContext = MockWebContext.create()
            .addRequestHeader(Pac4jConstants.CSRF_TOKEN, "wrong")
            .addSessionAttribute(Pac4jConstants.CSRF_TOKEN, VALUE);
    Assert.assertFalse(authorizer.isAuthorized(mismatchedContext, null));
}

