@Test
public void testFlush() throws IOException {
    OutputStream recordingStream = new OutputStream() {
        private boolean flushed;

        @Override
        public void write(int value) {
            // No bytes need to be recorded for this interaction test.
        }

        @Override
        public void flush() throws IOException {
            flushed = true;
            try {
                Thread.sleep(50L);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                throw new IOException(e);
            }
        }
    };

    SnifferOutputStream sos = new SnifferOutputStream(snifferSocket, recordingStream);
    ArgumentCaptor<Long> elapsedCaptor = ArgumentCaptor.forClass(Long.class);

    sos.flush();

    verify(snifferSocket).checkConnectionAllowed(1);
    verify(snifferSocket).logSocket(elapsedCaptor.capture());
    assertTrue("delegate flush should take a positive, bounded time",
            elapsedCaptor.getValue() >= 1L && elapsedCaptor.getValue() < 1000L);
}

