@Test
public void testInjectHtml() {
    SniffyConfiguration sniffyConfiguration = SniffyConfiguration.INSTANCE;
    String propertyName = "io.sniffy.injectHtml";
    String originalValue = System.getProperty(propertyName);

    try {
        System.setProperty(propertyName, "true");
        sniffyConfiguration.loadSniffyConfiguration();
        assertTrue(Boolean.TRUE.equals(sniffyConfiguration.getInjectHtmlEnabled()));

        System.setProperty(propertyName, "TRUE");
        sniffyConfiguration.loadSniffyConfiguration();
        assertTrue(Boolean.TRUE.equals(sniffyConfiguration.getInjectHtmlEnabled()));

        System.setProperty(propertyName, "false");
        sniffyConfiguration.loadSniffyConfiguration();
        assertTrue(Boolean.FALSE.equals(sniffyConfiguration.getInjectHtmlEnabled()));

        System.setProperty(propertyName, "");
        sniffyConfiguration.loadSniffyConfiguration();
        assertTrue(Boolean.FALSE.equals(sniffyConfiguration.getInjectHtmlEnabled()));

        System.clearProperty(propertyName);
        sniffyConfiguration.loadSniffyConfiguration();
        // With no override, the nullable configuration getter returns null.
        assertNull(sniffyConfiguration.getInjectHtmlEnabled());

        sniffyConfiguration.setInjectHtmlEnabled(Boolean.FALSE);
        assertTrue(Boolean.FALSE.equals(sniffyConfiguration.getInjectHtmlEnabled()));
    } finally {
        if (originalValue == null) {
            System.clearProperty(propertyName);
        } else {
            System.setProperty(propertyName, originalValue);
        }
        sniffyConfiguration.loadSniffyConfiguration();
    }
}

