@Test
public void testInjectAtTheBeginning() throws Exception {
    assertEquals(
            "<!DOCTYPE html><html><head><injected/><title>Title</title></head><body>Hello, World!</body></html>",
            injectAtTheBeginning("<!DOCTYPE html><html><head><title>Title</title></head><body>Hello, World!</body></html>")
    );
    assertEquals(
            "<!DOCTYPE html><html><injected/><title>Title</title></head><body>Hello, World!</body></html>",
            injectAtTheBeginning("<!DOCTYPE html><html><title>Title</title></head><body>Hello, World!</body></html>")
    );
    assertEquals(
            "<!DOCTYPE html><injected/><title>Title</title></head><body>Hello, World!</body></html>",
            injectAtTheBeginning("<!DOCTYPE html><title>Title</title></head><body>Hello, World!</body></html>")
    );
    assertEquals(
            "<title>Title</title><injected/><script>alert();</script></head><body>Hello, World!</body></html>",
            injectAtTheBeginning("<title>Title</title><script>alert();</script></head><body>Hello, World!</body></html>")
    );

    // A meta opening tag takes insertion priority over the head and script.
    assertEquals(
            "<!DOCTYPE html><html><head><meta name=\"x\"><injected/><script>alert();</script></head></html>",
            injectAtTheBeginning("<!DOCTYPE html><html><head><meta name=\"x\"><script>alert();</script></head></html>")
    );
    // A closing meta marker also determines the insertion position.
    assertEquals(
            "<!DOCTYPE html><html><head></meta><injected/><script>alert();</script></head></html>",
            injectAtTheBeginning("<!DOCTYPE html><html><head></meta><script>alert();</script></head></html>")
    );
    // With no closing angle bracket after the meta marker, placement falls through.
    assertEquals(
            "<meta<injected/><script>alert();</script>",
            injectAtTheBeginning("<meta<script>alert();</script>")
    );
    // No meta marker: insert after the head opening tag, before the script.
    assertEquals(
            "<html><head><injected/><script>alert();</script></head></html>",
            injectAtTheBeginning("<html><head><script>alert();</script></head></html>")
    );
    // A head appearing after the script cannot take priority.
    assertEquals(
            "<injected/><script>alert();</script><head></head>",
            injectAtTheBeginning("<script>alert();</script><head></head>")
    );
    // An html opening tag appearing after the script cannot take priority.
    assertEquals(
            "<injected/><script>alert();</script><html></html>",
            injectAtTheBeginning("<script>alert();</script><html></html>")
    );
}

