@Test
public void testGetRequest() throws Exception {
    MockHttpServletResponse response = new MockHttpServletResponse();
    MockHttpServletRequest request = MockMvcRequestBuilders.get(
            "/petclinic" + SnifferFilter.REQUEST_URI_PREFIX + "foo")
            .buildRequest(servletContext);
    cache.put("foo", Collections.singletonList(
            StatementMetaData.parse("SELECT 1 FROM DUAL", 300100999)));
    request.setContextPath("/petclinic");

    snifferServlet.service(request, response);

    assertEquals(HttpServletResponse.SC_OK, response.getStatus());
    assertEquals("application/json", response.getContentType());
    assertTrue(response.getContentLength() > 0);
    assertEquals("[{\"query\":\"SELECT 1 FROM DUAL\",\"time\":300.101}]",
            response.getContentAsString());

    // An absent cache entry returns no content and flushes the response buffer.
    MockHttpServletResponse missingResponse = new MockHttpServletResponse();
    MockHttpServletRequest missingRequest = MockMvcRequestBuilders.get(
            "/petclinic" + SnifferFilter.REQUEST_URI_PREFIX + "missing")
            .buildRequest(servletContext);
    missingRequest.setContextPath("/petclinic");

    snifferServlet.service(missingRequest, missingResponse);

    assertEquals(HttpServletResponse.SC_NO_CONTENT, missingResponse.getStatus());
    assertEquals(0, missingResponse.getContentLength());
    assertEquals("", missingResponse.getContentAsString());
}

@Test
public void testVerifyRangeThreadLocal() throws Exception {
    RecordedQueriesWithValue<String> recordedQueries = new RecordedQueriesWithValue<>("val");
    executeStatements(2);

    // Verify the query range for the current thread.
    recordedQueries.verifyRange(2, 2, Sniffer.CURRENT_THREAD);
    recordedQueries.verifyRange(1, 2, Sniffer.CURRENT_THREAD);
    recordedQueries.verifyRange(2, 3, Sniffer.CURRENT_THREAD);
    recordedQueries.verifyRange(1, 3, Sniffer.CURRENT_THREAD);

    try {
        recordedQueries.verifyRange(3, 4, Sniffer.CURRENT_THREAD);
        fail();
    } catch (AssertionError e) {
        assertNotNull(e);
    }

    try {
        recordedQueries.verifyRange(0, 1, Sniffer.CURRENT_THREAD);
        fail();
    } catch (AssertionError e) {
        assertNotNull(e);
    }

    assertEquals("val", recordedQueries.getValue());
}

